import datetime
from bisect import bisect_left, bisect_right
from functools import lru_cache

_ALLOWED_CHARS = frozenset("0123456789*,-/")

# Normal month lengths; index 0 is unused.
_MONTH_DAYS = (0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

# Maximum day that can ever exist in a month; February gets 29 for leap years.
_MAX_DAYS_IN_ANY_YEAR = (0, 31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

# Prefix masks for day-of-month bits 1..N.
_DOM_PREFIX = [0] * 32
_dom_prefix_mask = 0
for _d in range(1, 32):
    _dom_prefix_mask |= 1 << _d
    _DOM_PREFIX[_d] = _dom_prefix_mask

# Precomputed full-day tuples for month lengths.
_ALL_DAYS_BY_DIM = tuple(tuple(range(1, dim + 1)) for dim in range(32))

# Sakamoto/Gregorian offsets; _first_cron_weekday() returns Sunday=0.
_SAKAMOTO_MONTH_OFFSETS = (0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4)


def _to_int(s: str) -> int:
    """Parse a non-negative ASCII decimal integer."""
    if not s:
        raise ValueError("empty numeric value")
    value = 0
    for ch in s:
        if "0" <= ch <= "9":
            value = value * 10 + (ord(ch) - 48)
        else:
            raise ValueError("invalid numeric value")
    return value


def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _days_in_month(year: int, month: int) -> int:
    if month == 2 and _is_leap(year):
        return 29
    return _MONTH_DAYS[month]


def _first_cron_weekday(year: int, month: int) -> int:
    """
    Cron weekday for day 1 of the given month.
    Sunday=0, Monday=1, ..., Saturday=6.
    """
    y = year
    if month < 3:
        y -= 1
    return (
        y + y // 4 - y // 100 + y // 400
        + _SAKAMOTO_MONTH_OFFSETS[month - 1]
        + 1
    ) % 7


def _parse_field(field: str, lo: int, hi: int, is_dow: bool = False) -> int:
    """
    Parse one cron field into a bit mask.

    For day-of-week, raw values are 0..7 and both 0 and 7 mean Sunday,
    so value 7 is mapped to bit 0.
    """
    mask = 0

    for item in field.split(","):
        if not item:
            raise ValueError("empty item in field")

        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("invalid step syntax")

            base, step_s = parts
            step = _to_int(step_s)
            if step <= 0:
                raise ValueError("step must be at least 1")

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                rng = base.split("-")
                if len(rng) != 2:
                    raise ValueError("invalid range syntax")
                start = _to_int(rng[0])
                end = _to_int(rng[1])
            else:
                raise ValueError("step requires * or a range")

        elif item == "*":
            start, end = lo, hi
            step = 1

        elif "-" in item:
            rng = item.split("-")
            if len(rng) != 2:
                raise ValueError("invalid range syntax")
            start = _to_int(rng[0])
            end = _to_int(rng[1])
            step = 1

        else:
            value = _to_int(item)
            if value < lo or value > hi:
                raise ValueError("value out of range")
            if is_dow and value == 7:
                value = 0
            mask |= 1 << value
            continue

        if start > end:
            raise ValueError("range start must be <= range end")
        if start < lo or start > hi or end < lo or end > hi:
            raise ValueError("range out of bounds")

        for value in range(start, end + 1, step):
            if is_dow and value == 7:
                value = 0
            mask |= 1 << value

    if mask == 0:
        raise ValueError("field matches no values")
    return mask


def _mask_to_tuple(mask: int, lo: int, hi: int) -> tuple:
    return tuple(value for value in range(lo, hi + 1) if mask & (1 << value))


@lru_cache(maxsize=4096)
def _parse(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected exactly five cron fields")

    for field in fields:
        if not field or any(ch not in _ALLOWED_CHARS for ch in field):
            raise ValueError("invalid character in cron expression")

    minute_mask = _parse_field(fields[0], 0, 59)
    hour_mask = _parse_field(fields[1], 0, 23)
    month_mask = _parse_field(fields[2], 1, 12)
    dom_mask = _parse_field(fields[3], 1, 31)
    dow_mask = _parse_field(fields[4], 0, 7, is_dow=True)

    minutes = _mask_to_tuple(minute_mask, 0, 59)
    hours = _mask_to_tuple(hour_mask, 0, 23)
    months = _mask_to_tuple(month_mask, 1, 12)
    dom_list = _mask_to_tuple(dom_mask, 1, 31)

    if not minutes or not hours or not months or not dom_list:
        raise ValueError("field matches no values")

    # The special cron day rule depends on whether the raw field is exactly "*".
    dom_star = fields[3] == "*"
    dow_star = fields[4] == "*"

    # If day-of-week is exactly '*' and day-of-month is restricted,
    # the day-of-month field alone decides.  Detect impossible date sets.
    if dow_star and not dom_star:
        possible = False
        for month in months:
            max_day = _MAX_DAYS_IN_ANY_YEAR[month]
            if dom_mask & _DOM_PREFIX[max_day]:
                possible = True
                break
        if not possible:
            raise ValueError("cron expression can never fire")

    return (
        minutes,
        hours,
        months,
        month_mask,
        dom_mask,
        dow_mask,
        dom_star,
        dow_star,
        dom_list,
    )


def _time_from(hours: tuple, minutes: tuple, hour: int, minute: int):
    """
    Earliest (hour, minute) >= given time on the same day, or None.
    """
    hi = bisect_left(hours, hour)
    if hi == len(hours):
        return None

    h = hours[hi]
    if h > hour:
        return h, minutes[0]

    mi = bisect_left(minutes, minute)
    if mi < len(minutes):
        return h, minutes[mi]

    hi += 1
    if hi < len(hours):
        return hours[hi], minutes[0]
    return None


def _matching_days(
    dom_mask: int,
    dow_mask: int,
    dom_star: bool,
    dow_star: bool,
    dom_list: tuple,
    year: int,
    month: int,
) -> tuple:
    """
    Sorted days of the given month that match the cron day rules.
    """
    dim = _days_in_month(year, month)

    if dom_star and dow_star:
        return _ALL_DAYS_BY_DIM[dim]

    # If at least one day field is exactly '*', the other one decides alone.
    if dow_star:
        # Day-of-month decides alone.
        return dom_list[:bisect_right(dom_list, dim)]

    first_dow = _first_cron_weekday(year, month)

    if dom_star:
        # Day-of-week decides alone.
        result = []
        dow = first_dow
        for day in range(1, dim + 1):
            if dow_mask & (1 << dow):
                result.append(day)
            dow += 1
            if dow == 7:
                dow = 0
        return tuple(result)

    # Both are restricted: match either day-of-month or day-of-week.
    result = []
    dow = first_dow
    for day in range(1, dim + 1):
        if (dom_mask & (1 << day)) or (dow_mask & (1 << dow)):
            result.append(day)
        dow += 1
        if dow == 7:
            dow = 0
    return tuple(result)


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    (
        minutes,
        hours,
        months,
        month_mask,
        dom_mask,
        dow_mask,
        dom_star,
        dow_star,
        dom_list,
    ) = _parse(expr)

    # Fire times have second == 0 and microsecond == 0, and must be strictly
    # later than `after`.  Starting from the next whole minute handles both.
    try:
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    except OverflowError:
        raise ValueError("no next fire time is representable")

    year = start.year
    month = start.month
    day = start.day
    hour = start.hour
    minute = start.minute

    max_year = datetime.MAXYEAR

    while year <= max_year:
        # Advance to an allowed month if needed.
        if not (month_mask & (1 << month)):
            idx = bisect_left(months, month)
            if idx < len(months):
                month = months[idx]
            else:
                year += 1
                if year > max_year:
                    break
                month = months[0]
            day, hour, minute = 1, 0, 0
            continue

        days = _matching_days(
            dom_mask, dow_mask, dom_star, dow_star, dom_list, year, month
        )

        idx = bisect_left(days, day)
        if idx < len(days):
            candidate_day = days[idx]

            if candidate_day == day:
                tm = _time_from(hours, minutes, hour, minute)
                if tm is not None:
                    return datetime.datetime(year, month, candidate_day, tm[0], tm[1])
                idx += 1

            if idx < len(days):
                candidate_day = days[idx]
                return datetime.datetime(
                    year, month, candidate_day, hours[0], minutes[0]
                )

        # No suitable remaining day in this month; go to the next allowed month.
        idx = bisect_right(months, month)
        if idx < len(months):
            month = months[idx]
        else:
            year += 1
            if year > max_year:
                break
            month = months[0]

        day, hour, minute = 1, 0, 0

    raise ValueError("cron expression can never fire")
